        int_array ARRAY(INTEGER NOT NULL),
        enum_array_nullable ARRAY("SampleEnum"),
        enum_array ARRAY("SampleEnum" NOT NULL),
        object_array_nullable ARRAY(OBJECT("CustomAttribute")),
