CREATE DURABLE STREAM "codes" (
    CLASS "AlphaCodes" (
        currency VARCHAR NOT NULL ALPHANUMERIC(3),
        venue VARCHAR ALPHANUMERIC(4),
        segment VARCHAR ALPHANUMERIC(6),
        description VARCHAR
